#pragma once

#include "monstres/render/renderer.hpp"

#include <cstddef>
#include <optional>
#include <string>
#include <vector>

namespace monstres {

// Every mesh the game draws, in drawing order (opaque meshes first, then the
// transparent ones in this order). Most are model files in assets/models/
// (generated by tools/make_models.py, see that script for sizes and
// conventions); Ground and Path depend on the world and are built at runtime
// (see terrain_mesh.hpp).
enum class MeshId : size_t {
  Cube,
  Crate,
  Tree,
  Pine,
  Rock0, Rock1, Rock2, Rock3,
  Log,
  Stump,
  Bush,
  GrassShort,
  GrassTall,
  Flower,
  Cloud0, Cloud1, Cloud2,
  Mountain0, Mountain1,
  // Character parts (see src/render/characters.cpp).
  Eye,
  PlayerLeg, PlayerTorso, PlayerArm, PlayerHead, PlayerStaff, PlayerCrystal,
  CompanionBody, CompanionLeg, CompanionHead, CompanionEar, CompanionTail,
  SlimeBody,
  MushroomStem, MushroomCap, MushroomLeg,
  BirdBody, BirdWing, BirdLeg,
  // Village.
  HouseCottage, HouseChimney, HouseHut, Fence, Sign, Well, Barrel, Lamp,
  VillagerTorso, VillagerLeg, VillagerArm, VillagerHand, VillagerHead,
  HairShort, HairLong, HairBun, HatCap, HatStraw, HatBeanie,
  CrowBody, CrowWing, CrowLeg,
  FishBody, FishTail, FishFin,
  EyeIris, Horn, Bulb,  // variants of the monsters (tinted by the game)
  // Ruins of the tower.
  Tower, RuinWallLow, RuinWallHigh, Pillar, FallenPillar, Rubble, RuneStone,
  // The castle and the cave.
  CastleWall, CastleTower, CastleGate, CastleKeep, CaveMouth, Crystal, Teleporter,
  // Seen from afar (simplified).
  TreeFar, PineFar,
  Ground,  // built at runtime
  // Transparent, drawn last, in this order:
  Path,    // built at runtime
  Water,   // built at runtime
  Shadow,  // after the path so shadows fall on it
  Ripple,
  Smoke,
  Sparkle,
  RuneCircle,  // the capture seal
  Count
};
inline constexpr size_t kMeshCount = static_cast<size_t>(MeshId::Count);
inline constexpr size_t kRockVariants = 4;
inline constexpr size_t kCloudVariants = 3;
inline constexpr size_t kMountainVariants = 2;

// What a mesh is, for the frame statistics (RenderStats::triangles_by_group).
enum class MeshGroup : uint8_t { Terrain, Vegetation, Scenery, Characters, Effects, Sky };
inline MeshGroup mesh_group(MeshId id) {
  switch (id) {
    case MeshId::Ground: case MeshId::Path: case MeshId::Water: return MeshGroup::Terrain;
    case MeshId::GrassShort: case MeshId::GrassTall: case MeshId::Flower: return MeshGroup::Vegetation;
    case MeshId::Cloud0: case MeshId::Cloud1: case MeshId::Cloud2: case MeshId::Mountain0: case MeshId::Mountain1:
      return MeshGroup::Sky;
    case MeshId::Shadow: case MeshId::Ripple: case MeshId::Smoke: case MeshId::Sparkle: case MeshId::RuneCircle:
      return MeshGroup::Effects;
    default: break;
  }
  const auto i = static_cast<size_t>(id);
  if (i >= static_cast<size_t>(MeshId::Eye) && i <= static_cast<size_t>(MeshId::BirdLeg)) return MeshGroup::Characters;
  if (i >= static_cast<size_t>(MeshId::VillagerTorso) && i <= static_cast<size_t>(MeshId::Bulb)) return MeshGroup::Characters;
  return MeshGroup::Scenery;
}

inline MeshId mesh_offset(MeshId first, size_t i) {
  return static_cast<MeshId>(static_cast<size_t>(first) + i);
}

// File name (without .glb) of a model, or nullptr for runtime meshes.
const char* model_name(MeshId id);

// Loads a glTF binary file (.glb): every triangle primitive of every node,
// with node transforms applied. Missing normals are computed (flat), missing
// colors are white. Returns nullopt and fills `error` on failure.
std::optional<MeshData> load_model(const std::string& path, std::string* error = nullptr);

// Loads every model file of `dir`. The result is indexed by MeshId; runtime
// meshes are left empty. Returns false and fills `error` if a file fails.
bool load_models(const std::string& dir, std::vector<MeshData>& meshes, std::string* error = nullptr);

}  // namespace monstres
